// UpdatedAtLT applies the LT predicate on the "updated_at" field.
func UpdatedAtLT(v time.Time) predicate.PerformanceReview {
	return predicate.PerformanceReview(sql.FieldLT(FieldUpdatedAt, v))
}

// UpdatedAtLTE applies the LTE predicate on the "updated_at" field.
func UpdatedAtLTE(v time.Time) predicate.PerformanceReview {
	return predicate.PerformanceReview(sql.FieldLTE(FieldUpdatedAt, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PerformanceReview) predicate.PerformanceReview {
	return predicate.PerformanceReview(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PerformanceReview) predicate.PerformanceReview {
	return predicate.PerformanceReview(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PerformanceReview) predicate.PerformanceReview {
	return predicate.PerformanceReview(sql.NotPredicates(p))
}
